<section aria-labelledby="schedules"><h2 id="schedules">Private schedules</h2><ol>@forelse($schedules as $schedule)<li><h3>{{ $schedule->public_id }}</h3><p>{{ $schedule->state }} · every {{ $schedule->frequency_hours }} hours · next {{ $schedule->next_run_at }} · {{ $schedule->missed_runs }} missed</p><form method="post" action="{{ route('account.monitoring.control', $schedule->public_id) }}">@csrf<label>Control<select name="action"><option>pause</option><option>resume</option><option>delete</option></select></label><button>Apply</button></form><details><summary>Notification and threshold preferences</summary><form method="post" action="{{ route('account.monitoring.control', $schedule->public_id) }}">@csrf<input type="hidden" name="action" value="preferences"><label>Changed categories threshold<input name="minimum_changed_categories" type="number" min="1" max="6" value="{{ $schedule->thresholds['minimum_changed_categories'] }}"></label><label><input type="checkbox" name="email_on_material_change" value="1" @checked($schedule->notification_preferences['email_on_material_change'])> Email on material change</label><button>Save preferences</button></form></details><h4>Recent comparisons</h4><ol>@foreach($schedule->comparisons as $comparison)<li>{{ $comparison->material ? 'Material change' : 'Below threshold' }} · source categories: {{ implode(', ', array_column($comparison->source_changes, 'category')) ?: 'none' }} · version drift: {{ implode(', ', array_column($comparison->version_drift, 'kind')) ?: 'none' }} · evidence versions: {{ implode(', ', array_column($comparison->evidence_citations, 'version_id')) }}</li>@endforeach</ol><h4>Recent runs</h4><ol>@foreach($schedule->runs as $run)<li>{{ $run->public_id }} · {{ $run->state }} · scheduled {{ $run->scheduled_for }} @if(in_array($run->state,['queued','running','failed']))<form method="post" action="{{ route('account.monitoring.runs.control', $run->public_id) }}">@csrf<label>Run action<select name="action"><option>cancel</option><option>retry</option></select></label><button>Apply</button></form>@endif</li>@endforeach</ol></li>@empty<li>No monitoring schedules.</li>@endforelse</ol></section></main></body></html>
